1	/****************************************************************************
2	 * apps/vendor/allwinnertech/apps/luncher_dm/dm_als.c
3	 * LTR553 ALS 环境光服务层（P153：锁屏亮度显示 + 暗光开灯提醒）
4	 *
5	 * 架构（与 dm_weather / dm_ld2410b 同款后台轮询风格）：
6	 *   dm_als_init()   → orb_subscribe_multi(ORB_ID(sensor_light)) + LVGL 1s timer
7	 *   dm_als_timer_cb → poll + orb_copy → 更新 s_cur_lux（供 UI 显示）
8	 *                     暗光状态机（阈值/防抖/冷却）→ 触发 dm_als_set_dark_cb
9	 *   dm_als_get_lux()→ 锁屏健康卡每秒读取显示（文本去重由 UI 层做）
10	 *
11	 * 驱动侧：ltr553.c 轮询线程计算 lux → push_event(SENSOR_TYPE_LIGHT) →
12	 * uORB sensor_light（float light 单位 lux）。本模块只订阅不写驱动。
13	 ****************************************************************************/
14	
15	#include <nuttx/config.h>
16	#include <poll.h>
17	#include <errno.h>
18	#include <string.h>
19	/* P153：uORB 接口与 luncher_dm.c 一致（sensor_temp/humi 同款）——
20	 * sensor_light 结构由 <sensor/light.h> 提供（uORB topic 头），
21	 * orb_* API 在 <uORB/uORB.h>。勿改用 nuttx/uorb.h（结构未导出）。 */
22	#include <sensor/light.h>
23	#include <uORB/uORB.h>
24	
25	#include <lvgl.h>
26	
27	#include "dm_als.h"
28	
29	/* ── 全局状态 ── */
30	static int          s_light_fd = -1;   /* sensor_light 订阅 fd */
31	static int          s_cur_lux  = -1;   /* 最近一次 lux（int，-1=无数据） */
32	static dm_als_dark_cb_t s_dark_cb = NULL;
33	
34	/* 暗光状态机（实际行为）：连续暗光只触发一次；光线恢复后再次变暗，
35	 * 距上次触发 ≥ 冷却期才再次弹窗（限频）。s_dark_active 期间不重复触发。 */
36	static bool         s_dark_active = false;   /* 当前处于暗光状态（未恢复） */
37	static bool         s_seen_bright = false;   /* P157：见过 lux≥确认阈值（确认真实工作） */
38	static lv_timer_t  *s_poll_timer = NULL;
39	static uint32_t     s_start_ms   = 0;        /* P156：init 时刻（开机稳定期基准） */
40	
41	static void dm_als_timer_cb(lv_timer_t *timer);
42	
43	/****************************************************************************
44	 * 内部：暗光状态机 tick（每次拿到新 lux 调用一次）
45	 ****************************************************************************/
46	static void dm_als_dark_tick(int lux, uint32_t now_ms)
47	{
48	    static uint32_t s_debounce_start = 0;   /* 进入暗光候选的起始时刻 */
49	    static uint32_t s_last_trigger  = 0;    /* 上次弹窗时刻（冷却） */
50	
51	    /* P157 确认门已移除（2026-09-04）：传感器清洁后能正常读数，
52	     * 无需等待 ≥200 lux 才启用暗光检测。仅保留开机稳定期保险。 */
53	
54	    /* P156：开机稳定期内不触发暗光弹窗——驱动首个有效 ALS 转换前
55	     * 可能持续推 0（CH0 未就绪），开机即弹"知道了"是误报 */
56	    if (now_ms - s_start_ms < DM_ALS_STARTUP_MS)
57	        return;
58	
59	    bool dark_now = (lux >= 0) && (lux < DM_ALS_DARK_LUX);
60	
61	    if (dark_now) {
62	        if (!s_dark_active) {
63	            /* 刚进入暗光：记录候选起点，等 debounce 确认 */
64	            if (s_debounce_start == 0)
65	                s_debounce_start = now_ms;
66	            if (now_ms - s_debounce_start >= DM_ALS_DARK_DEBOUNCE_MS) {
67	                /* 防抖通过：确认暗光 */
68	                s_dark_active = true;
69	                s_debounce_start = 0;
70	                /* 冷却检查：距上次触发 ≥ 冷却期才再次提醒 */
71	                if (s_last_trigger == 0 ||
72	                    now_ms - s_last_trigger >= DM_ALS_DARK_COOLDOWN_MS) {
73	                    s_last_trigger = now_ms;
74	                    syslog(LOG_INFO, "[als] dark_tick TRIGGER lux=%d cb=%s\n",
75	                           lux, s_dark_cb ? "set" : "NULL");
76	                    if (s_dark_cb)
77	                        s_dark_cb();
78	                }
79	            }
80	        }
81	        /* 已确认暗光：保持，不重复触发（冷却已含） */
82	    }
83	    else {
84	        /* 光线恢复：重置状态机 */
85	        s_dark_active = false;
86	        s_debounce_start = 0;
87	    }
88	}
89	
90	/****************************************************************************
91	 * 内部：LVGL 轮询 timer（1s）
92	 ****************************************************************************/
93	static void dm_als_timer_cb(lv_timer_t *timer)
94	{
95	    (void)timer;
96	    struct sensor_light light;
97	    struct pollfd fds;
98	    int ret;
99	
100	    if (s_light_fd < 0)
101	        return;
102	
103	    fds.fd = s_light_fd;
104	    fds.events = POLLIN;
105	    fds.revents = 0;
106	
107	    ret = poll(&fds, 1, 0);
108	    if (ret <= 0)
109	        return;   /* 无新数据：正常（驱动按自己的节奏推送） */
110	
111	    if (orb_copy(ORB_ID(sensor_light), s_light_fd, &light) == OK) {
112	        int lux = (int)light.light;
113	        if (lux < 0)
114	            lux = 0;
115	        s_cur_lux = lux;
116	        dm_als_dark_tick(lux, lv_tick_get());
117	    }
118	}
119	
120	/****************************************************************************
121	 * 公开接口
122	 ****************************************************************************/
123	int dm_als_init(void)
124	{
125	    if (s_light_fd >= 0)
126	        return 0;   /* 已初始化 */
127	
128	    s_light_fd = orb_subscribe_multi(ORB_ID(sensor_light), 0);
129	    if (s_light_fd < 0) {
130	        /* 无 LTR553 ALS：不打扰（锁屏亮度行显示 "--"） */
131	        return -1;
132	    }
133	
134	    s_poll_timer = lv_timer_create(dm_als_timer_cb, DM_ALS_POLL_MS, NULL);
135	    if (!s_poll_timer) {
136	        /* timer 创建失败：释放订阅 fd，避免 fd 泄漏 + 亮度永远 "--" */
137	        orb_unsubscribe(s_light_fd);
138	        s_light_fd = -1;
139	        return -1;
140	    }
141	    lv_timer_set_repeat_count(s_poll_timer, -1);   /* 无限循环 */
142	    s_start_ms = lv_tick_get();   /* P156：开机稳定期基准（init 时刻） */
143	
144	    return 0;
145	}
146	
147	int dm_als_get_lux(void)
148	{
149	    return s_cur_lux;
150	}
151	
152	void dm_als_set_dark_cb(dm_als_dark_cb_t cb)
153	{
154	    s_dark_cb = cb;
155	}

