763	static void set_flowctrl(struct uart_dev_s *dev){
764	#ifndef CONFIG_SUPPRESS_UART_CONFIG
765	  struct up_dev_s *priv = (struct up_dev_s *)dev->priv;
766	  /* Enable Auto-Flow Control in the Modem Control Register */
767	  if ((priv->port == 1 || priv->port == 2 || priv->port == 3) && priv->hwflowctrl) {
768		uint32_t value = arm_serialin(priv, R528_UART_MCR_OFFSET);
769		value |= UART_MCR_DTR | UART_MCR_RTS | UART_MCR_AFCE;
770		arm_serialout(priv, R528_UART_MCR_OFFSET, value);
771	
772		/* enable with modem status interrupts */
773		value = arm_serialin(priv, R528_UART_IER_OFFSET);
774		value |= UART_IER_EDSSI;
775		priv->ier = value;
776		arm_serialout(priv, R528_UART_IER_OFFSET, value);
777	  }else if((priv->port == 1 || priv->port == 2 || priv->port == 3) && (priv->hwflowctrl==0)){
778		/* disable with modem status interrupts */
779		uint32_t value = arm_serialin(priv, R528_UART_IER_OFFSET);
780		value &= (~UART_IER_EDSSI);
781		priv->ier = value;
782		arm_serialout(priv, R528_UART_IER_OFFSET, value);
783		/* disable Auto-Flow Control in the Modem Control Register */
784		value = arm_serialin(priv, R528_UART_MCR_OFFSET);
785		value &= ((~UART_MCR_DTR)&(~UART_MCR_RTS)&(~UART_MCR_AFCE));
786		arm_serialout(priv, R528_UART_MCR_OFFSET, value);
787	  }
788	#endif
789	}
