/* 把一段原始字节渲染为文本并追加。
 * ASCII 模式：可打印直出，\r\n 归一为 \n；非打印转 '.'。
 * HEX 模式：每行16字节 "00 11 22 ..." 末尾附 ASCII 预览。 */
static void uart_dbg_feed(const uint8_t *buf, int n)
{
    char tmp[512];
    int  ti = 0;

    if (!uart_dbg_hex_mode) {
        /* ── ASCII 模式（原有逻辑） ── */
        for (int i = 0; i < n; i++) {
            uint8_t b = buf[i];
            if (b == '\r') continue;
            if (ti >= (int)sizeof(tmp) - 2) {
                tmp[ti] = '\0';
                uart_dbg_append(tmp);
                ti = 0;
            }
            if (b == '\n')      tmp[ti++] = '\n';
            else if (b >= 0x20 && b < 0x7F) tmp[ti++] = (char)b;
            else                tmp[ti++] = '.';
        }
    } else {
        /* ── HEX 模式：每行16字节 hex + ASCII 预览 ── */
        static int hex_off = 0;   /* 行内偏移（跨 feed 调用保持） */
        for (int i = 0; i < n; i++) {
            if (hex_off == 0) {
                ti += snprintf(tmp + ti, sizeof(tmp) - ti, "%04X: ", i);
            }
            ti += snprintf(tmp + ti, sizeof(tmp) - ti, "%02X ", buf[i]);
            hex_off++;
            if (hex_off >= 16 || i == n - 1) {
                /* 补齐 + ASCII 预览 */
                for (int j = hex_off; j < 16; j++)
                    ti += snprintf(tmp + ti, sizeof(tmp) - ti, "   ");
                ti += snprintf(tmp + ti, sizeof(tmp) - ti, " |");
                for (int j = i - hex_off + 1; j <= i; j++) {
                    uint8_t c = buf[j];
                    tmp[ti++] = (c >= 0x20 && c < 0x7F) ? (char)c : '.';
                }
                ti += snprintf(tmp + ti, sizeof(tmp) - ti, "|\n");
                hex_off = 0;
            }
            if (ti >= (int)sizeof(tmp) - 48) {
                tmp[ti] = '\0';
                uart_dbg_append(tmp);
                ti = 0;
            }
        }
    }

    if (ti > 0) {
        tmp[ti] = '\0';
        uart_dbg_append(tmp);
    }
}

