/* 键盘高度（DM_SCALE=2.4，DM(130)=312px，适配 Montserrat 24px 4行按键） */
#define UART_DBG_KB_H  DM(130)
/* 输入栏高度 + 与键盘/终端间距 */
#define INPUT_BAR_H    DM(50)
#define INPUT_GAP      DM(8)

/* 键盘事件：回车=发送，隐藏时恢复终端+输入栏 */
static void uart_dbg_kb_event_cb(lv_event_t *e)
{
    lv_event_code_t code = lv_event_get_code(e);
    lv_obj_t *kb = lv_event_get_current_target(e);

    if (code == LV_EVENT_READY) {
        uart_dbg_send_cb(NULL);
    } else if (code == LV_EVENT_CANCEL) {
        lv_obj_add_flag(kb, LV_OBJ_FLAG_HIDDEN);
        if (uart_dbg_ta)
            lv_obj_clear_state(uart_dbg_ta, LV_STATE_FOCUSED);
        lv_coord_t sw = lv_disp_get_hor_res(lv_disp_get_default());
        lv_coord_t sh = lv_disp_get_ver_res(lv_disp_get_default());
        /* 终端恢复：工具栏下方到输入栏上方 */
        lv_coord_t term_y = TOP_BAR_H + DM(44);
        lv_coord_t term_h = sh - INPUT_BAR_H - INPUT_GAP - term_y;
        lv_obj_set_size(uart_dbg_term, sw - 2 * EDGE_PAD, term_h);
        /* 输入栏回到屏幕底部 */
        lv_obj_t *bar = (uart_dbg_ta) ? lv_obj_get_parent(uart_dbg_ta) : NULL;
        if (bar) {
            lv_obj_set_pos(bar, EDGE_PAD, sh - INPUT_BAR_H - INPUT_GAP);
            assert(EDGE_PAD + (sw - 2 * EDGE_PAD) <= sw &&
                   sh - INPUT_BAR_H - INPUT_GAP + INPUT_BAR_H <= sh &&
                   "uart_dbg: 输入栏越界");
        }
        uart_dbg_scroll_bottom();
    }
}

/* 输入框聚焦 → 键盘弹出 + 输入栏移到键盘上方 + 终端缩小 */
static void uart_dbg_ta_focused_cb(lv_event_t *e)
{
    (void)e;
    reset_idle_timer();
    if (!uart_dbg_kb || !uart_dbg_term)
        return;
    lv_obj_clear_flag(uart_dbg_kb, LV_OBJ_FLAG_HIDDEN);
    lv_coord_t sw = lv_disp_get_hor_res(lv_disp_get_default());
    lv_coord_t sh = lv_disp_get_ver_res(lv_disp_get_default());
    lv_coord_t term_y = TOP_BAR_H + DM(44);
    /* 输入栏移到键盘正上方：sh - KB_H - GAP - INPUT_H */
    lv_coord_t input_y = sh - UART_DBG_KB_H - INPUT_GAP - INPUT_BAR_H;
    lv_obj_t *bar = (uart_dbg_ta) ? lv_obj_get_parent(uart_dbg_ta) : NULL;
